ALL_SLIDES = [{'id': 1, 'title': 'Weaving Mats', 'tag': 'Paper Weaving • Row Instructions & Grid Patterns', 'lecture': 'Welcome to our geometry and pattern studio! We begin our exploration with the ancient art of weaving, which connects mathematical periodicity to everyday craft. To make a paper weaving mat, we take a sheet of colored paper, fold it in half, and make parallel slits from the fold line to within one centimetre of the outer edge. This slit sheet serves as the warp, or the fixed vertical base. Next, we cut bright contrasting paper strips to act as the weft, or the horizontal weaving threads. Weaving proceeds row by row following clear algorithmic rules. A classic plain weave uses the rule: one over, one under, repeated across the row. In the second row, we must invert the rule: one under, one over! Why must we invert the sequence? If we do not invert it, the horizontal strip simply slides out because it lacks interlacing tension! By altering the numerical rules, such as two over, one under, or three over, two under, intricate geometric chevron and diamond patterns emerge on grid paper. Notice how mathematical parity—alternating between odd and even positions—creates both structural strength and aesthetic symmetry.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Paper weaving combines spatial geometry, sequence algorithms, and structural tension through interlacing vertical slits (warp) and horizontal strips (weft).\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 flex items-center gap-2">\n                            <span>📐</span> The Weaving Algorithm\n                        </h4>\n                        <ul class="text-xs space-y-2 text-slate-300">\n                            <li>• <strong>Warp (Vertical Base):</strong> Folded paper with parallel cuts forming fixed vertical bands.</li>\n                            <li>• <strong>Weft (Horizontal Strips):</strong> Movable colored strips woven horizontally through the warp.</li>\n                            <li>• <strong>Standard Alternating Weave:</strong>\n                                <ul class="pl-4 mt-1 space-y-1 font-mono text-[11px] text-amber-300">\n                                    <li>Row 1: 1 Over, 1 Under, 1 Over, 1 Under...</li>\n                                    <li>Row 2: 1 Under, 1 Over, 1 Under, 1 Over...</li>\n                                    <li>Row 3: 1 Over, 1 Under, 1 Over, 1 Under...</li>\n                                </ul>\n                            </li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-cyan-500/30">\n                        <h4 class="font-bold text-cyan-400 mb-2 flex items-center gap-2">\n                            <span>🎨</span> Advanced Pattern Rules\n                        </h4>\n                        <ul class="text-xs space-y-2 text-slate-300">\n                            <li>• <strong>Twill Weave (2 Over, 1 Under):</strong> Shifting the starting point by 1 unit each row produces diagonal staircases and herringbone textures.</li>\n                            <li>• <strong>Basket Weave (2 Over, 2 Under):</strong> Creates bold checkerboard blocks of paired colors.</li>\n                            <li>• <strong>Structural Principle:</strong> Interlacing locks paper fibers perpendicularly, preventing the mat from unravelling.</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-indigo-950/40 border border-indigo-500/30 rounded-lg text-xs text-indigo-200">\n                    <strong>Binary Matrix Insight:</strong> A woven mat can be represented as a mathematical grid of 1s (strip over) and 0s (strip under), where alternating rows satisfy the parity rule <em>Cell(r, c) = (r + c) mod 2</em>.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_1', 'checkpoints': [{'question': "In a standard alternating weave, if Row 1 follows '1 over, 1 under', what must Row 2 follow to lock the paper strips?", 'options': ['1 under, 1 over', '1 over, 1 under (same as Row 1)', '2 over, 2 under', 'All over'], 'correct': 0, 'explanation': "Row 2 must invert the sequence to '1 under, 1 over' so the strip is held firmly by the alternating warp bands."}, {'question': "On a grid of 8 columns, how many 'over' positions are there in a row following '1 over, 1 under'?", 'options': ['4 over positions', '8 over positions', '2 over positions', '6 over positions'], 'correct': 0, 'explanation': 'With 8 columns alternating 1 over and 1 under, exactly half (8 ÷ 2 = 4) are over positions.'}]}, {'id': 2, 'title': 'Plane Tessellations', 'tag': 'Tiling & Tessellation • Covering Surfaces Without Gaps or Overlaps', 'lecture': 'Look down at tiled floors in train stations, verandas, and historic monuments: identical tiles cover the entire surface completely without leaving any gaps or overlapping one another! In mathematics, covering an infinite two-dimensional plane with repeating shapes is called a tessellation, or tiling. Why do certain geometric shapes tile seamlessly while others fail? The secret lies in vertex angles! When tiles meet around a single vertex point, their interior angles must add up to exactly 360 degrees, completing a full circle. Consider a square: each corner has a right angle of 90 degrees. When four squares meet at a vertex, four times 90 equals exactly 360 degrees! The tiles fit flush without leaving any space. Now consider an equilateral triangle: each corner is 60 degrees. Six triangles meeting at a point give six times 60, which equals 360 degrees! Now look at a regular hexagon: each corner is 120 degrees. Three hexagons meeting at a vertex give three times 120, which equals 360 degrees! This is why honeybees build hexagonal honeycombs: hexagons tile the plane with the least boundary wax, proving the power of geometric efficiency.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    A tessellation is a pattern formed by repeating figures that completely covers a plane with no gaps and no overlapping regions.\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-3 gap-3 text-xs">\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-emerald-500/30">\n                        <h4 class="font-bold text-emerald-400 mb-1.5 flex items-center gap-1.5">\n                            <span>🟦</span> Square Tiling\n                        </h4>\n                        <p class="text-slate-300">• Corner Angle: <strong>90°</strong></p>\n                        <p class="text-slate-300">• Tiles per Vertex: <strong>4</strong></p>\n                        <p class="font-mono text-emerald-300 font-bold">• 4 × 90° = 360° ✓</p>\n                        <p class="text-slate-400 text-[11px] mt-1">Found in graph paper, floor tiles, and chessboards.</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-cyan-500/30">\n                        <h4 class="font-bold text-cyan-400 mb-1.5 flex items-center gap-1.5">\n                            <span>🔺</span> Triangular Tiling\n                        </h4>\n                        <p class="text-slate-300">• Corner Angle: <strong>60°</strong></p>\n                        <p class="text-slate-300">• Tiles per Vertex: <strong>6</strong></p>\n                        <p class="font-mono text-cyan-300 font-bold">• 6 × 60° = 360° ✓</p>\n                        <p class="text-slate-400 text-[11px] mt-1">Forms rigid isometric grids and bridge trusses.</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-amber-500/30">\n                        <h4 class="font-bold text-amber-400 mb-1.5 flex items-center gap-1.5">\n                            <span>⬡</span> Hexagonal Tiling\n                        </h4>\n                        <p class="text-slate-300">• Corner Angle: <strong>120°</strong></p>\n                        <p class="text-slate-300">• Tiles per Vertex: <strong>3</strong></p>\n                        <p class="font-mono text-amber-300 font-bold">• 3 × 120° = 360° ✓</p>\n                        <p class="text-slate-400 text-[11px] mt-1">Nature\'s choice for beehive honeycombs and basalt columns.</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-emerald-950/40 border border-emerald-500/30 rounded-lg text-xs text-emerald-200">\n                    <strong>The 360° Vertex Invariant:</strong> Only shapes whose interior angles evenly divide 360° can form monohedral regular tessellations of the plane!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_2', 'checkpoints': [{'question': 'Why do regular hexagons tile a flat plane without gaps?', 'options': ['Because three 120° angles meet at a vertex: 3 × 120° = 360°', 'Because they have 6 sides', 'Because they are shaped like circles', 'Because 6 × 90° = 540°'], 'correct': 0, 'explanation': 'A regular hexagon has interior angles of 120°. Exactly 3 hexagons meet around a point: 3 × 120° = 360°, completely filling the vertex.'}, {'question': 'How many equilateral triangles must meet at a vertex to tessellate the plane?', 'options': ['6 triangles', '4 triangles', '5 triangles', '3 triangles'], 'correct': 0, 'explanation': 'Each angle of an equilateral triangle is 60°. Since 360° ÷ 60° = 6, exactly 6 triangles meet at each vertex.'}]}, {'id': 3, 'title': 'Polygon Tiling', 'tag': 'Exploring Shapes • Why Pentagons Fail & Multi-Shape Tilings', 'lecture': 'What happens if we attempt to tile a floor using regular pentagons, which have five equal sides? Let us do the mathematics. In a regular pentagon, each interior corner angle measures 108 degrees. If we place three regular pentagons around a vertex, three times 108 equals 324 degrees. That leaves an unfilled gap of 360 minus 324, which is 36 degrees! But a fourth pentagon needs 108 degrees, which is far too wide, causing it to overlap! Because 108 does not divide 360 evenly, regular pentagons can never tile the plane alone! Now test regular octagons, which have eight sides. Each interior corner of an octagon is 135 degrees. Two octagons meeting at a point occupy two times 135 equals 270 degrees. To reach 360 degrees, we need an angle of 360 minus 270, which is exactly 90 degrees! What shape has 90-degree corners? A square! By pairing octagons with small squares, we create a magnificent semi-regular tessellation. We can also combine triangles, squares, and rhombuses to design intricate multi-shape tiling pavements.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Shapes whose interior angles do not evenly divide 360° cannot tile alone, but can form hybrid tessellations when paired with matching partner shapes.\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-rose-500/30">\n                        <h4 class="font-bold text-rose-400 mb-2 flex items-center gap-2">\n                            <span>❌</span> Why Regular Pentagons Fail\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• Interior angle of regular pentagon = <strong>108°</strong>.</li>\n                            <li>• 3 pentagons at a vertex: 3 × 108° = <strong>324°</strong>.</li>\n                            <li>• Remaining gap = 360° - 324° = <strong class="text-amber-300">36°</strong>.</li>\n                            <li>• 4 pentagons: 4 × 108° = <strong>432° > 360°</strong> (overlap!).</li>\n                            <li>• Conclusion: 360 ÷ 108 = 3.33 (not a whole number). Pentagons cannot tile alone!</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 flex items-center gap-2">\n                            <span>✓</span> Octagon-Square Hybrid Tiling\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• Interior angle of regular octagon = <strong>135°</strong>.</li>\n                            <li>• 2 octagons at a vertex: 2 × 135° = <strong>270°</strong>.</li>\n                            <li>• Deficit angle to complete 360°: 360° - 270° = <strong class="text-cyan-300">90°</strong>.</li>\n                            <li>• A square has 90° corners: <strong>135° + 135° + 90° = 360°</strong>!</li>\n                            <li>• Octagons and squares tile the plane together in perfect harmony.</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-slate-800/80 border border-slate-700 rounded-lg text-xs text-slate-300">\n                    <strong>Only Three Regular Monotilings:</strong> There are only three regular polygons that can tile the plane by themselves: the <em>Equilateral Triangle</em>, the <em>Square</em>, and the <em>Regular Hexagon</em>.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_3', 'checkpoints': [{'question': 'What is the angle gap left when three regular pentagons meet around a point?', 'options': ['36°', '45°', '54°', '0°'], 'correct': 0, 'explanation': '3 × 108° = 324°. The remaining gap around the 360° vertex is 360° - 324° = 36°.'}, {'question': 'Which shape fills the vertex gap between two regular octagons (135° each) to make 360°?', 'options': ['Square (90°)', 'Equilateral triangle (60°)', 'Hexagon (120°)', 'Pentagon (108°)'], 'correct': 0, 'explanation': 'Two octagons take 135° + 135° = 270°. The remaining angle is 360° - 270° = 90°, which is exactly the corner angle of a square.'}]}, {'id': 4, 'title': 'Triangle Types', 'tag': 'Classification by Sides & Angles • Rhombus Dissection', 'lecture': 'Triangles are three-sided polygons, the most fundamental rigid building blocks of geometry. We can classify every triangle by the relationships among its three sides and three angles. First, take a rhombus cutout and fold it along both its diagonals. When cut along the diagonals, the rhombus divides into four identical right-angled triangles! Examine the properties of triangles carefully. An equilateral triangle has all three sides equal in length, and all three interior angles equal to 60 degrees. An isosceles triangle has exactly two sides of equal length. By folding an isosceles triangle down its central line of symmetry, the two side edges match perfectly, proving that the two base angles opposite the equal sides are also completely equal! Finally, a scalene triangle has three sides of completely different lengths, and consequently all three interior angles have different measures. Remember the golden angle sum property: in every triangle, regardless of its shape or size, the three interior angles always add up to exactly 180 degrees, forming a straight angle!', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Triangles are classified into three distinct families based on the equality of their side lengths and interior angles:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-3 gap-3 text-xs">\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-emerald-500/30">\n                        <h4 class="font-bold text-emerald-400 mb-1.5 flex items-center gap-1.5">\n                            <span>🔺</span> Equilateral Triangle\n                        </h4>\n                        <p class="text-slate-300">• Sides: <strong>All 3 equal</strong> (a = b = c)</p>\n                        <p class="text-slate-300">• Angles: <strong>All 3 equal = 60°</strong></p>\n                        <p class="text-slate-300">• Symmetry: <strong>3 lines of symmetry</strong></p>\n                        <p class="font-mono text-emerald-300 font-bold mt-1">• 60° + 60° + 60° = 180°</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-cyan-500/30">\n                        <h4 class="font-bold text-cyan-400 mb-1.5 flex items-center gap-1.5">\n                            <span>📐</span> Isosceles Triangle\n                        </h4>\n                        <p class="text-slate-300">• Sides: <strong>At least 2 equal</strong></p>\n                        <p class="text-slate-300">• Angles: <strong>2 base angles equal</strong></p>\n                        <p class="text-slate-300">• Symmetry: <strong>1 line of symmetry</strong></p>\n                        <p class="font-mono text-cyan-300 font-bold mt-1">• If sides equal, opp angles equal!</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-rose-500/30">\n                        <h4 class="font-bold text-rose-400 mb-1.5 flex items-center gap-1.5">\n                            <span>📏</span> Scalene Triangle\n                        </h4>\n                        <p class="text-slate-300">• Sides: <strong>All 3 different</strong></p>\n                        <p class="text-slate-300">• Angles: <strong>All 3 different</strong></p>\n                        <p class="text-slate-300">• Symmetry: <strong>0 lines of symmetry</strong></p>\n                        <p class="font-mono text-rose-300 font-bold mt-1">• Sum still equals 180°</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-indigo-950/40 border border-indigo-500/30 rounded-lg text-xs text-indigo-200">\n                    <strong>Rhombus Dissection:</strong> Cutting a rhombus along its perpendicular diagonals divides it into 4 congruent right-angled scalene (or isosceles) triangles meeting at 90°.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_4', 'checkpoints': [{'question': 'In an isosceles triangle, if the two equal sides are 7 cm and the third side is 4 cm, what is true about its angles?', 'options': ['Two of its angles are equal', 'All three angles are 60°', 'All three angles are different', 'It must have a right angle'], 'correct': 0, 'explanation': 'In an isosceles triangle, the angles opposite the equal sides are always equal.'}, {'question': 'If two angles of a triangle are 50° and 60°, what is the third angle, and what type of triangle is it?', 'options': ['70° (Scalene triangle)', '60° (Equilateral triangle)', '50° (Isosceles triangle)', '90° (Right triangle)'], 'correct': 0, 'explanation': 'Third angle = 180° - (50° + 60°) = 180° - 110° = 70°. Since all angles (50°, 60°, 70°) are different, all sides are different: a scalene triangle.'}]}, {'id': 5, 'title': 'Kite Geometry', 'tag': 'Quadrilateral Properties • Adjacent Equal Sides & Diagonal Symmetry', 'lecture': 'During the vibrant harvest festival of Makar Sankranti, millions of colorful kites soar into the clear blue sky. Have you ever stopped to investigate the exact geometric definition of a kite? In mathematics, a kite is a quadrilateral—a four-sided polygon—with a very special side relationship. Unlike a parallelogram where opposite sides are equal, in a kite, two pairs of adjacent, neighboring sides are equal in length! The two shorter top sides are equal to each other, and the two longer bottom sides are equal to each other. Now look at the internal diagonals of a kite. Fold a kite paper model along its long vertical axis: the left half folds over and matches the right half perfectly! This vertical diagonal is an axis of symmetry. When we draw the second horizontal diagonal, something wonderful occurs: the two diagonals intersect at exactly 90 degrees, forming perpendicular right angles! Furthermore, the main vertical diagonal bisects the horizontal cross-diagonal, cutting it into two equal halves. These geometric properties give the kite aerodynamic balance in the wind.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    A kite is a quadrilateral characterized by two pairs of equal-length adjacent sides and mutually perpendicular diagonals.\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n                        <h4 class="font-bold text-amber-400 mb-2 flex items-center gap-2">\n                            <span>🪁</span> Side & Angle Properties\n                        </h4>\n                        <ul class="text-slate-300 space-y-2">\n                            <li>• <strong>Adjacent Equal Sides:</strong> Top pair AB = AD, bottom pair CB = CD.</li>\n                            <li>• <strong>Opposite Sides:</strong> Are <em>not</em> equal (AB ≠ CD).</li>\n                            <li>• <strong>One Pair of Equal Angles:</strong> The angles between the unequal sides are equal (∠ B = ∠ D).</li>\n                            <li>• <strong>Line of Symmetry:</strong> The main diagonal AC is a line of reflective symmetry.</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-cyan-500/30">\n                        <h4 class="font-bold text-cyan-400 mb-2 flex items-center gap-2">\n                            <span>✛</span> Diagonal Relationships\n                        </h4>\n                        <ul class="text-slate-300 space-y-2">\n                            <li>• <strong>Perpendicular Diagonals:</strong> The two diagonals cross at a <strong>90° right angle</strong> (AC ⊥ BD).</li>\n                            <li>• <strong>Bisecting Property:</strong> The vertical diagonal bisects the horizontal cross-diagonal into two equal segments.</li>\n                            <li>• <strong>Special Case (Rhombus):</strong> A rhombus is an equilateral kite where all 4 sides are equal!</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-amber-950/40 border border-amber-500/30 rounded-lg text-xs text-amber-200">\n                    <strong>Aerodynamic Geometry:</strong> The symmetry axis and perpendicular cross-struts provide maximum stability and wind resistance when flying in the sky.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_5', 'checkpoints': [{'question': 'Which statement correctly defines a kite quadrilateral?', 'options': ['A quadrilateral with two pairs of adjacent equal sides', 'A quadrilateral with two pairs of opposite equal sides', 'A quadrilateral with four equal angles of 90°', 'A shape with only 3 sides'], 'correct': 0, 'explanation': 'A kite has two pairs of adjacent (neighboring) sides that are equal in length.'}, {'question': 'At what angle do the diagonals of a kite intersect?', 'options': ['90° (Perpendicular)', '60°', '45°', '180°'], 'correct': 0, 'explanation': 'The diagonals of any kite are always perpendicular, meeting at 90°.'}]}, {'id': 6, 'title': 'Parallelograms and Rectangles', 'tag': 'Quadrilateral Taxonomy • Opposites, Rights Angles & Rhombuses', 'lecture': 'Let us expand our quadrilateral gallery to investigate parallelograms, rectangles, and rhombuses. Picture a flexible wooden frame made of four hinged rods. When opposite sides are parallel and equal in length, the shape is a parallelogram. In any parallelogram, opposite sides are equal, and opposite angles are equal! Now take this slanted parallelogram frame and push it upright until all four interior angles become crisp 90-degree right angles. What have you created? A rectangle! A rectangle is a special parallelogram with four right angles. Because it is a parallelogram, its opposite sides are still equal, but its diagonals now have the remarkable property of being exactly equal in length! Next, take a frame where all four sides are equal in length: that is a rhombus. In a rhombus, opposite sides are parallel, but all four sides are equal, and its diagonals intersect at 90 degrees. Finally, what if a shape has four equal sides AND four right angles? That is a square! A square is the king of quadrilaterals: simultaneously a rectangle, a rhombus, and a parallelogram.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    The quadrilateral family tree connects parallelograms, rectangles, rhombuses, and squares through progressive angle and side constraints:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 flex items-center gap-2">\n                            <span>▱</span> Parallelogram vs Rectangle\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>Parallelogram:</strong> Opposite sides parallel & equal; opposite angles equal; diagonals bisect each other.</li>\n                            <li>• <strong>Rectangle:</strong> A parallelogram where <strong>all 4 angles = 90°</strong>.</li>\n                            <li>• <strong>Diagonal Invariant:</strong> In a rectangle, the two diagonals are <strong>equal in length</strong> (d₁ = d₂).</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n                        <h4 class="font-bold text-emerald-400 mb-2 flex items-center gap-2">\n                            <span>◇</span> Rhombus vs Square\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>Rhombus:</strong> A parallelogram where <strong>all 4 sides are equal</strong>; diagonals cross at <strong>90°</strong>.</li>\n                            <li>• <strong>Square:</strong> Combines rectangle and rhombus properties: 4 equal sides AND 4 right angles (90°)!</li>\n                            <li>• <strong>Hierarchy:</strong> Every square is a rectangle, every square is a rhombus, and all are parallelograms.</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-indigo-950/40 border border-indigo-500/30 rounded-lg text-xs text-indigo-200">\n                    <strong>Diagonal Diagnostic:</strong> Bisect each other ➔ Parallelogram; Equal length ➔ Rectangle; Perpendicular (90°) ➔ Rhombus or Kite; Both equal and perpendicular ➔ Square!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_6', 'checkpoints': [{'question': 'Which property is true for a rectangle but NOT necessarily true for all parallelograms?', 'options': ['All four angles are 90° right angles', 'Opposite sides are equal', 'Opposite sides are parallel', 'Diagonals bisect each other'], 'correct': 0, 'explanation': 'All four angles being 90° is the defining property of a rectangle. General parallelograms have slanted angles.'}, {'question': 'A quadrilateral has 4 equal sides and diagonals that cross at 90°, but its angles are not 90°. What shape is it?', 'options': ['A rhombus', 'A square', 'A rectangle', 'A trapezoid'], 'correct': 0, 'explanation': 'A shape with 4 equal sides and non-right angles is a rhombus.'}]}, {'id': 7, 'title': 'Seven Tangrams', 'tag': 'Tangram Puzzle • Geometric Dissection & Shape Synthesis', 'lecture': "Originating in ancient China, the tangram is one of the world's most famous geometric dissection puzzles. A single square is cut into exactly seven geometric pieces, known as tans: two large right-angled triangles, one medium right-angled triangle, two small right-angled triangles, one small square, and one parallelogram. Notice that all five triangles in the tangram set are isosceles right-angled triangles, meaning each has one 90-degree corner and two 45-degree corners! This common angle relationship allows the pieces to combine in astonishing ways. For instance, putting the two small triangles together hypotenuse-to-hypotenuse forms the small square! Joining them leg-to-leg forms the medium triangle or the parallelogram! Using all seven pieces without overlapping, we can form animals, boats, dancers, and even recreate the original large square. Tangrams teach us spatial transformation: complex structures can be dissected into simpler shapes, and simple shapes can synthesize infinite artistic and mathematical forms.", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    The 7-piece tangram puzzle decomposes a unit square into proportional geometric tiles sharing 45°, 90°, and 135° angles:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-violet-500/30">\n                        <h4 class="font-bold text-violet-400 mb-2 flex items-center gap-2">\n                            <span>🧩</span> The 7 Tan Pieces\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>2 Large Triangles:</strong> Each has area = 1/4 of total square.</li>\n                            <li>• <strong>1 Medium Triangle:</strong> Area = 1/8 of total square.</li>\n                            <li>• <strong>2 Small Triangles:</strong> Each area = 1/16 of total square.</li>\n                            <li>• <strong>1 Square:</strong> Area = 1/8 of total square.</li>\n                            <li>• <strong>1 Parallelogram:</strong> Area = 1/8 of total square.</li>\n                            <li>• All 5 triangles are <strong>45°-45°-90° isosceles triangles</strong>!</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-teal-500/30">\n                        <h4 class="font-bold text-teal-400 mb-2 flex items-center gap-2">\n                            <span>🔄</span> Equivalent Compositions\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• 2 Small Triangles = <strong>1 Square</strong> (hypotenuse joined).</li>\n                            <li>• 2 Small Triangles = <strong>1 Medium Triangle</strong> (legs joined).</li>\n                            <li>• 2 Small Triangles = <strong>1 Parallelogram</strong> (reversed legs joined).</li>\n                            <li>• 2 Large Triangles + 1 Medium + 2 Small + 1 Square + 1 Parallelogram = <strong>1 Big Whole Square</strong>!</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-violet-950/40 border border-violet-500/30 rounded-lg text-xs text-violet-200">\n                    <strong>Conservation of Area:</strong> No matter how the 7 pieces are rearranged (into a swan, a running person, or a house), the total surface area remains exactly equal to the original square.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_7', 'checkpoints': [{'question': 'How many triangles are there in a standard 7-piece tangram set?', 'options': ['5 triangles', '4 triangles', '7 triangles', '3 triangles'], 'correct': 0, 'explanation': 'A standard tangram has 5 triangles (2 large, 1 medium, 2 small), 1 square, and 1 parallelogram (total 7 pieces).'}, {'question': 'What shape can be formed by joining the two small tangram triangles along their longest side (hypotenuse)?', 'options': ['The small square', 'A hexagon', 'The large triangle', 'A circle'], 'correct': 0, 'explanation': 'Joining the hypotenuses of two 45°-45°-90° small triangles forms a square identical to the tangram square.'}]}, {'id': 8, 'title': 'Shape Riddles', 'tag': 'Which Shape Am I? • Deductive Geometry Logic & Property Matching', 'lecture': "Put on your mathematical detective hats for our popular game: 'Which Shape Am I?' In this inquiry, we use logical deduction to identify mystery geometric figures from forensic property clues. Clue one: 'I am a quadrilateral. All four of my sides are equal in length, but none of my corner angles are 90 degrees. Which shape am I?' Since all four sides are equal, it must be either a square or a rhombus; because its angles are not 90 degrees, it is definitively a rhombus! Clue two: 'I am a polygon. I have two pairs of adjacent sides that are equal, but my opposite sides are not parallel. My diagonals cross at perpendicular right angles. Which shape am I?' That is the hallmark of a kite! Clue three: 'I am a four-sided polygon. My opposite sides are parallel and equal, but my diagonals are of different lengths and do not meet at 90 degrees.' That is a general parallelogram! Clue four: 'I have four sides, two pairs of parallel opposite sides, and two equal diagonals.' That is a rectangle! By linking geometric definitions to precise properties, you master the deductive language of geometry.", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Test your deductive geometry skills by analyzing property clues to identify mystery 2-D shapes:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-3 text-xs">\n                    <div class="p-3 bg-slate-800/80 rounded-xl border border-cyan-500/30">\n                        <span class="font-bold text-cyan-400 block mb-1">Riddle 1</span>\n                        <p class="text-slate-300 italic mb-1">"I have 4 equal sides, 4 right angles, and equal perpendicular diagonals."</p>\n                        <p class="font-mono text-emerald-300 font-bold">➔ Answer: Square</p>\n                    </div>\n                    <div class="p-3 bg-slate-800/80 rounded-xl border border-amber-500/30">\n                        <span class="font-bold text-amber-400 block mb-1">Riddle 2</span>\n                        <p class="text-slate-300 italic mb-1">"I have 4 sides. Opposite sides are equal, all angles are 90°, and diagonals are equal."</p>\n                        <p class="font-mono text-emerald-300 font-bold">➔ Answer: Rectangle</p>\n                    </div>\n                    <div class="p-3 bg-slate-800/80 rounded-xl border border-purple-500/30">\n                        <span class="font-bold text-purple-400 block mb-1">Riddle 3</span>\n                        <p class="text-slate-300 italic mb-1">"I have 4 equal sides, opposite angles are equal, but no right angles."</p>\n                        <p class="font-mono text-emerald-300 font-bold">➔ Answer: Rhombus</p>\n                    </div>\n                    <div class="p-3 bg-slate-800/80 rounded-xl border border-rose-500/30">\n                        <span class="font-bold text-rose-400 block mb-1">Riddle 4</span>\n                        <p class="text-slate-300 italic mb-1">"Adjacent pairs of sides are equal, diagonals are perpendicular, exactly 1 line of symmetry."</p>\n                        <p class="font-mono text-emerald-300 font-bold">➔ Answer: Kite</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-slate-800/80 border border-slate-700 rounded-lg text-xs text-slate-300">\n                    <strong>Deduction Strategy:</strong> Filter shapes step-by-step: 1. Count sides ➔ 2. Check side equality ➔ 3. Inspect corner angles ➔ 4. Check diagonal properties.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_8', 'checkpoints': [{'question': 'A shape has 4 sides, opposite sides are parallel and equal, but its diagonals are NOT equal in length. What shape is it?', 'options': ['A parallelogram', 'A rectangle', 'A square', 'A circle'], 'correct': 0, 'explanation': 'In a general parallelogram, diagonals are of unequal length (one long, one short). If diagonals were equal, it would be a rectangle.'}, {'question': 'Which quadrilateral has exactly one line of reflective symmetry and perpendicular diagonals?', 'options': ['Kite', 'Parallelogram', 'Rhombus', 'Scalene triangle'], 'correct': 0, 'explanation': 'A kite has exactly one line of reflective symmetry (down its main diagonal) and perpendicular diagonals.'}]}, {'id': 9, 'title': 'Folding Kites', 'tag': 'Make Your Own Kite • Step-by-Step Origami Geometry', 'lecture': 'Origami—the ancient Japanese art of paper folding—is pure tactile geometry! In our workshop, we fold an exact physical kite shape starting from a single square sheet of paper. Step one: take a square paper and fold it in half along one of its diagonal corners to form a sharp crease line. Unfold it: this diagonal serves as our central axis of symmetry. Step two: take the top-left edge of the square and fold it inward so that it lies perfectly flush along the diagonal crease. Step three: take the top-right edge and fold it symmetrically inward along the same diagonal crease. Press both folds firmly! Look at the shape you have created: it is an authentic mathematical kite! The two top folded edges are equal to each other, and the two bottom edges of the original square are equal to each other. The diagonal crease bisects the top vertex angle, and by placing a straight bamboo sliver along the horizontal corners, you see that the two diagonals meet at a strict 90-degree right angle. Paper folding proves that complex geometric theorems are physically verifiable right in your hands.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Paper folding creates precise geometric forms through angle bisections and line reflections along a square\'s diagonal axis:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n                        <h4 class="font-bold text-amber-400 mb-2 flex items-center gap-2">\n                            <span>📄</span> The Origami Folding Sequence\n                        </h4>\n                        <ol class="text-slate-300 space-y-2 list-decimal pl-4">\n                            <li><strong>Start with a Square:</strong> 4 equal sides and 4 right angles (90°).</li>\n                            <li><strong>Diagonal Crease:</strong> Fold diagonally corner-to-corner to form line of symmetry AC.</li>\n                            <li><strong>Left Wing Fold:</strong> Fold top-left edge inward along diagonal AC.</li>\n                            <li><strong>Right Wing Fold:</strong> Fold top-right edge symmetrically inward along diagonal AC.</li>\n                            <li><strong>Result:</strong> A true geometric kite with 2 pairs of adjacent equal sides!</li>\n                        </ol>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n                        <h4 class="font-bold text-emerald-400 mb-2 flex items-center gap-2">\n                            <span>📐</span> Geometric Verifications\n                        </h4>\n                        <ul class="text-slate-300 space-y-2">\n                            <li>• <strong>Angle Bisection:</strong> The diagonal fold bisects the original 90° corner into two equal 45° angles.</li>\n                            <li>• <strong>Congruent Triangles:</strong> The kite consists of two mirror-image right-angled triangles folded across the diagonal.</li>\n                            <li>• <strong>Perpendicular Struts:</strong> Attaching horizontal bamboo cross-struts forms the 90° diagonal intersection.</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-amber-950/40 border border-amber-500/30 rounded-lg text-xs text-amber-200">\n                    <strong>Origami Axiom:</strong> Folding a straight edge onto another creates an exact angle bisector without using a protractor!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_9', 'checkpoints': [{'question': 'What is the initial fold made on a square paper to construct an origami kite?', 'options': ['Fold along the diagonal corner-to-corner', 'Fold horizontally across the middle', 'Fold in four equal squares', 'Cut off the corners'], 'correct': 0, 'explanation': 'Folding diagonally corner-to-corner establishes the central axis of symmetry for the kite wings.'}, {'question': 'When both top edges are folded along the diagonal crease, what property is guaranteed?', 'options': ['The two top folded edges are equal in length', 'All four sides become equal', 'The shape becomes a circle', 'The diagonals become curved'], 'correct': 0, 'explanation': 'Because the folds are symmetric reflections along the diagonal, the two top folded edges are identical in length.'}]}, {'id': 10, 'title': 'Circle Geometry', 'tag': 'Play with Circles • Compass Construction & Inscribed Quadrilaterals', 'lecture': "A circle is the most symmetrical curve in the universe: every point on its boundary lies at the exact same distance from a central fixed point! Using a pencil compass, we anchor the metal needle at the centre O and sweep the pencil around to trace the circumference. The fixed distance between the needle and pencil is the radius. A straight line passing through the centre from one edge of the circle to the opposite edge is a diameter. Every diameter equals exactly twice the radius, and all diameters of a circle are equal in length. Now let us conduct a fascinating geometric experiment: draw two diameters inside a circle and connect their four endpoints with straight lines to form an inscribed quadrilateral. What shape emerges? If the two diameters cross at an arbitrary angle, connecting their four endpoints produces a rectangle! Why? Because the two diameters are equal in length and bisect each other at the circle's centre. But if you make the two diameters intersect at exactly 90 degrees—perpendicular to each other—connecting their endpoints produces a perfect square! Circles generate the most fundamental quadrilaterals of geometry.", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Diameters inscribed in a circle act as diagonals of geometric quadrilaterals whose vertices lie on the circumference:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-cyan-500/30">\n                        <h4 class="font-bold text-cyan-400 mb-2 flex items-center gap-2">\n                            <span>⭕</span> Core Circle Metrics\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>Centre (O):</strong> The unique point equidistant from all points on the circumference.</li>\n                            <li>• <strong>Radius (r):</strong> Distance from centre to any boundary point.</li>\n                            <li>• <strong>Diameter (d):</strong> Longest straight line passing through the centre: <strong class="text-cyan-300">d = 2r</strong>.</li>\n                            <li>• <strong>Chord:</strong> Any line segment connecting two points on the circle.</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 flex items-center gap-2">\n                            <span>🟩</span> Inscribed Quadrilateral Theorem\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>Case 1 (Non-Perpendicular Diameters):</strong> Any two diameters have equal length (d₁ = d₂) and bisect at O. Connecting endpoints yields a <strong class="text-amber-300">Rectangle</strong>!</li>\n                            <li>• <strong>Case 2 (Perpendicular Diameters at 90°):</strong> The two equal diameters cross at 90°. Connecting endpoints yields a <strong class="text-emerald-300">Square</strong>!</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-cyan-950/40 border border-cyan-500/30 rounded-lg text-xs text-cyan-200">\n                    <strong>Thales\' Theorem:</strong> Any angle inscribed in a semicircle is a right angle (90°). Because diagonals are diameters, all 4 corner angles must be 90°!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_10', 'checkpoints': [{'question': 'If the radius of a circle drawn with a compass is 4.5 cm, what is the length of its diameter?', 'options': ['9 cm', '4.5 cm', '18 cm', '13.5 cm'], 'correct': 0, 'explanation': 'Diameter = 2 × radius = 2 × 4.5 cm = 9 cm.'}, {'question': 'When two diameters of a circle intersect at a 90° right angle, connecting their four endpoints always produces which shape?', 'options': ['A square', 'A parallelogram', 'A kite', 'A scalene triangle'], 'correct': 0, 'explanation': 'Because the diagonals are equal, bisect each other, and cross at 90°, the inscribed shape is a square.'}]}, {'id': 11, 'title': 'Circle Art', 'tag': 'Circle Designs • String Art & Modular Chord Patterns', 'lecture': 'Circles are not just mechanical tools—they are canvases for stunning geometric art! In our circle design studio, we divide the circumference of a circle into 24 equally spaced points, numbered sequentially from 1 to 24 like a giant clockface. By connecting these points using straight rule chords, breathtaking curved illusions and star polygons come alive. This technique is called string art or curve stitching. For example, if we use a constant jump rule—connecting point n to point n plus 5 (so point 1 connects to 6, point 6 connects to 11, point 11 to 16, and so on)—a beautiful 24-pointed geometric star emerges! If we use a multiplication modulo rule—connecting point n to two times n (so point 1 to 2, 2 to 4, 3 to 6, 4 to 8)—the straight lines envelop a delicate heart-shaped curve called a cardioid! Straight lines, when drawn following systematic mathematical rules across a circle, create the optical illusion of smooth organic curves.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    String art and envelope geometry connect numbered points on a circle using straight chord segments to generate radiant star polygons and caustic curves:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-violet-500/30">\n                        <h4 class="font-bold text-violet-400 mb-2 flex items-center gap-2">\n                            <span>⭐</span> Constant Step Jump Rule (n ➔ n + k)\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• 24 points spaced evenly by 360° ÷ 24 = 15° each.</li>\n                            <li>• <strong>Step 5:</strong> 1 ➔ 6 ➔ 11 ➔ 16 ➔ 21 ➔ 2 ... produces a sharp 24-pointed woven star.</li>\n                            <li>• <strong>Step 7:</strong> Connects points with longer chords, creating an inner circular ring boundary.</li>\n                            <li>• If step k and 24 share no common factors (coprime), the string visits all 24 points in a single unbroken loop!</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-rose-500/30">\n                        <h4 class="font-bold text-rose-400 mb-2 flex items-center gap-2">\n                            <span>💖</span> Modular Multiplication (n ➔ 2n (mod 24))\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• Point 1 connects to 2; Point 2 to 4; Point 3 to 6; Point 4 to 8.</li>\n                            <li>• Point 12 connects to 24; Point 13 connects to 26 = 2.</li>\n                            <li>• <strong>Enveloping Caustic:</strong> The dense lines form a curved optical envelope known as a <strong>Cardioid</strong>!</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-violet-950/40 border border-violet-500/30 rounded-lg text-xs text-violet-200">\n                    <strong>Envelope Geometry:</strong> Pure straight chords tangents to an invisible curved caustic boundary, proving how straight-line mathematics creates curved artistic beauty.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_11', 'checkpoints': [{'question': 'On a circle divided into 24 points, what is the angle between each consecutive numbered point?', 'options': ['15°', '24°', '10°', '30°'], 'correct': 0, 'explanation': '360° ÷ 24 points = 15° between each adjacent point.'}, {'question': 'Starting at point 1 on a 24-point circle with a step jump of 7, which point is connected next?', 'options': ['Point 8', 'Point 7', 'Point 14', 'Point 9'], 'correct': 0, 'explanation': '1 + 7 = Point 8.'}]}, {'id': 12, 'title': 'Cube Nets', 'tag': 'Spatial Reasoning • 11 Hexomino Nets & 3-D Cube Folding', 'lecture': 'Step into the three-dimensional world! A solid cube has six square faces, twelve straight edges, and eight corner vertices. If we take scissors and cut along seven edges of a hollow cardboard cube, it unrolls flat onto a table. This two-dimensional unfolded pattern is called a net! How many distinct ways can six connected squares fold up into a closed cube? In mathematics, there are exactly eleven unique cube nets—no more, no less! Not every arrangement of six squares works. For example, six squares in a single straight row of six will wrap around four sides, leaving two overlapping on the top while leaving the bottom gaping open! A four-in-a-row arrangement with one flap on top and one flap on the bottom—known as a T-net or cross-net—folds into a perfect cube. In a folded cube, opposite faces never touch each other; in a net, opposite faces are always separated by exactly one intervening square. Testing nets develops powerful spatial 3D mental rotation.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    A cube net is a flat arrangement of six connected squares that can be folded along its edges to construct a hollow 3-D cube:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 flex items-center gap-2">\n                            <span>📦</span> Cube Metrics & Net Rules\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>Faces:</strong> 6 identical congruent squares.</li>\n                            <li>• <strong>Edges:</strong> 12 straight equal line segments.</li>\n                            <li>• <strong>Vertices:</strong> 8 corner points where 3 faces meet.</li>\n                            <li>• <strong>Exactly 11 Distinct Nets:</strong> Only 11 hexomino patterns can fold into a closed cube.</li>\n                            <li>• <strong>Opposite Face Rule:</strong> In any linear strip of a net, opposite faces are separated by exactly 1 square.</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-rose-500/30">\n                        <h4 class="font-bold text-rose-400 mb-2 flex items-center gap-2">\n                            <span>❌</span> Illegal Net Configurations\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>6 in a line:</strong> Fails (faces overlap, leaving ends open).</li>\n                            <li>• <strong>2×2 block of 4 squares:</strong> Fails (cannot fold closed).</li>\n                            <li>• <strong>Corner clusters:</strong> If 4 squares meet at a single vertex point, they cannot fold without colliding.</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-indigo-950/40 border border-indigo-500/30 rounded-lg text-xs text-indigo-200">\n                    <strong>Standard Die Invariant:</strong> On standard gaming dice, numbers on opposite faces always sum to 7: 1 opposite 6, 2 opposite 5, and 3 opposite 4!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_12', 'checkpoints': [{'question': 'How many total distinct unfolded nets can form a closed cube?', 'options': ['11 nets', '6 nets', '14 nets', '8 nets'], 'correct': 0, 'explanation': 'Mathematicians have proven there are exactly 11 valid hexomino nets that fold into a closed cube.'}, {'question': 'On a standard die net, if the top face is 3, what number must be on the opposite bottom face?', 'options': ['4', '5', '6', '2'], 'correct': 0, 'explanation': 'Opposite faces on a die sum to 7. 7 - 3 = 4.'}]}, {'id': 13, 'title': 'Painted Cubes', 'tag': 'Cube Connections • 3×3×3 Dissection & Painted Face Counting', 'lecture': 'Here is one of the most famous spatial reasoning challenges in all of school mathematics: The Painted Cube Puzzle! Imagine a solid wooden cube measuring 3 centimetres by 3 centimetres by 3 centimetres. We dip this entire cube into a vat of bright red paint so that all six exterior faces are painted red. Once the paint dries, a carpenter cuts the cube with saws into tiny 1-centimetre solid cubes. How many small cubes are formed? 3 times 3 times 3 equals 27 small cubes in total. Now examine the paint on these 27 small cubes! The 8 cubes located at the outer corners have three faces painted red. The cubes located along the edges, between the corners, have two faces painted red: each of the 12 edges has one such cube, giving 12 cubes with two painted faces. The cubes located in the exact centre of each of the 6 faces have only one face painted red, giving 6 cubes with one painted face. And in the very dark, hidden heart of the large cube sits exactly one inner cube that received zero paint at all! 8 plus 12 plus 6 plus 1 equals exactly 27 cubes.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Analyzing a 3 × 3 × 3 painted cube dissection categorizes the 27 unit cubes by their spatial coordinates and exterior exposures:\n                </p>\n                <div class="overflow-x-auto">\n                    <table class="w-full text-xs text-left bg-slate-800/80 rounded-xl border border-slate-700">\n                        <thead class="bg-slate-700/60 text-emerald-300">\n                            <tr>\n                                <th class="p-2.5">Cube Category</th>\n                                <th class="p-2.5">Spatial Location</th>\n                                <th class="p-2.5">Painted Faces</th>\n                                <th class="p-2.5">Formula (n=3)</th>\n                                <th class="p-2.5">Count</th>\n                            </tr>\n                        </thead>\n                        <tbody class="divide-y divide-slate-700/60 text-slate-200 font-mono">\n                            <tr>\n                                <td class="p-2 font-bold text-rose-400">Corners</td>\n                                <td class="p-2">8 exterior corners</td>\n                                <td class="p-2 text-amber-300 font-bold">3 faces</td>\n                                <td class="p-2">Fixed (always 8)</td>\n                                <td class="p-2 font-bold text-white">8</td>\n                            </tr>\n                            <tr>\n                                <td class="p-2 font-bold text-cyan-400">Edge Middles</td>\n                                <td class="p-2">Centres of 12 edges</td>\n                                <td class="p-2 text-amber-300 font-bold">2 faces</td>\n                                <td class="p-2">12 × (n - 2)</td>\n                                <td class="p-2 font-bold text-white">12</td>\n                            </tr>\n                            <tr>\n                                <td class="p-2 font-bold text-indigo-400">Face Centres</td>\n                                <td class="p-2">Centres of 6 faces</td>\n                                <td class="p-2 text-amber-300 font-bold">1 face</td>\n                                <td class="p-2">6 × (n - 2)²</td>\n                                <td class="p-2 font-bold text-white">6</td>\n                            </tr>\n                            <tr>\n                                <td class="p-2 font-bold text-slate-400">Central Core</td>\n                                <td class="p-2">Interior hidden center</td>\n                                <td class="p-2 text-slate-500 font-bold">0 faces</td>\n                                <td class="p-2">(n - 2)³</td>\n                                <td class="p-2 font-bold text-white">1</td>\n                            </tr>\n                            <tr class="bg-slate-900/60 font-bold">\n                                <td class="p-2 text-emerald-400" colspan="4">Total Small Cubes (n³)</td>\n                                <td class="p-2 text-emerald-400 text-sm">27</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                <div class="p-3 bg-emerald-950/40 border border-emerald-500/30 rounded-lg text-xs text-emerald-200">\n                    <strong>Sum Verification:</strong> 8{ (corners)} + 12{ (edges)} + 6{ (faces)} + 1{ (core)} = 27{ small cubes} (3 × 3 × 3 = 27).\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_13', 'checkpoints': [{'question': 'In a 3×3×3 painted cube, how many small cubes have exactly 3 faces painted?', 'options': ['8 cubes (the corners)', '12 cubes', '6 cubes', '1 cube'], 'correct': 0, 'explanation': 'Only the 8 corner cubes have 3 exposed exterior faces painted.'}, {'question': 'How many small cubes in a 3×3×3 painted cube have ZERO painted faces?', 'options': ['1 cube (the inner core)', '0 cubes', '8 cubes', '6 cubes'], 'correct': 0, 'explanation': 'There is exactly 1 cube buried completely inside the centre: (3 - 2)³ = 1³ = 1 cube.'}]}, {'id': 14, 'title': 'Shape Puzzles', 'tag': 'Linear Clue Puzzles • Positional Geometry & Deductive Ordering', 'lecture': "Mathematics exercises our deductive powers through positional logic puzzles. Picture a row of five pedestals numbered one through five from left to right. Five geometric shapes—a Circle, a Square, a Triangle, a Hexagon, and a Rectangle—must be placed on these pedestals following a set of strict clues. Clue one: 'The Circle is located somewhere to the left of the Triangle.' Clue two: 'The Hexagon sits at the exact centre on pedestal three.' Clue three: 'The Square is immediately between the Triangle and the Rectangle.' Clue four: 'The Triangle is not at an outer edge.' Let us deduce step by step! Pedestal three is locked: it must be the Hexagon. Since the Triangle is not at an outer edge, it cannot be on pedestal five; and since the Square sits between the Triangle and the Rectangle, pedestals two, three, and four or pedestals four, five must be examined. Because the Hexagon is on three, the block of Triangle, Square, and Rectangle must occupy pedestals two, four, and five or similar. By testing clues systematically, every shape locks into its unique pedestal position.", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Positional logic puzzles combine spatial orientation, relational constraints, and elimination to determine unique linear arrangements:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 flex items-center gap-2">\n                            <span>🔍</span> The Puzzle Clues\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>5 Pedestals:</strong> Position 1 (Left) to Position 5 (Right).</li>\n                            <li>• <strong>Clue 1 (Anchor):</strong> The <strong>Hexagon</strong> is on Position 3 (Exact Centre).</li>\n                            <li>• <strong>Clue 2 (Adjacency):</strong> The <strong>Square</strong> is directly between <strong>Triangle</strong> and <strong>Rectangle</strong>.</li>\n                            <li>• <strong>Clue 3 (Order):</strong> The <strong>Circle</strong> is on the far left (Position 1).</li>\n                            <li>• <strong>Clue 4 (Non-Edge):</strong> The <strong>Triangle</strong> is not on Position 5.</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n                        <h4 class="font-bold text-emerald-400 mb-2 flex items-center gap-2">\n                            <span>💡</span> Step-by-Step Solution\n                        </h4>\n                        <ol class="text-slate-300 space-y-1.5 list-decimal pl-4">\n                            <li>Position 1 = <strong>Circle</strong> (Clue 3).</li>\n                            <li>Position 3 = <strong>Hexagon</strong> (Clue 1).</li>\n                            <li>Position 2 = <strong>Triangle</strong> (Clue 4).</li>\n                            <li>Positions 4 and 5: Square is between Triangle (Pos 2) and Rectangle (Pos 5) with Hexagon on 3.</li>\n                            <li>Therefore, the unique valid line is: <strong>Circle, Triangle, Hexagon, Square, Rectangle</strong>!</li>\n                        </ol>\n                    </div>\n                </div>\n                <div class="p-3 bg-indigo-950/40 border border-indigo-500/30 rounded-lg text-xs text-indigo-200">\n                    <strong>Elimination Principle:</strong> Anchor absolute positions first, then test contiguous blocks to eliminate impossible permutations.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_14', 'checkpoints': [{'question': 'If the Hexagon is at the exact centre of 5 positions, what is its position number?', 'options': ['Position 3', 'Position 2', 'Position 4', 'Position 1'], 'correct': 0, 'explanation': 'In 5 positions (1, 2, 3, 4, 5), the exact centre is Position 3.'}, {'question': 'In the deduction above, which shape sits at Position 1 on the far left?', 'options': ['Circle', 'Square', 'Hexagon', 'Triangle'], 'correct': 0, 'explanation': 'Clue 3 directly anchors the Circle at Position 1 on the far left.'}]}, {'id': 15, 'title': 'Platonic Solids', 'tag': "Icosahedron & Dodecahedron • Regular Polyhedra & Euler's Formula", 'lecture': "We now encounter the most majestic geometric solids in three dimensions: the Platonic Solids! A Platonic solid is a regular polyhedron where every face is an identical regular polygon, and the exact same number of faces meet at every single vertex. In our textbook cutouts, we construct two magnificent Platonic solids: the icosahedron and the dodecahedron. Look first at the icosahedron: its name comes from the Greek word 'icosa', meaning twenty! It has twenty equilateral triangular faces, twelve vertices, and thirty edges. Five triangles meet at each vertex. Next, look at the dodecahedron: 'dodeca' means twelve! It has twelve regular pentagonal faces, twenty vertices, and thirty edges. Three pentagons meet at each vertex. Now look at the edges of both solids: thirty edges each! The great mathematician Leonhard Euler discovered a universal law for all convex polyhedra: Vertices minus Edges plus Faces always equals 2! For the icosahedron: 12 minus 30 plus 20 equals 2. For the dodecahedron: 20 minus 30 plus 12 equals 2! Euler's formula binds all polyhedra together.", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    The five Platonic solids are the only convex polyhedra with identical regular polygon faces meeting at identical vertices:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs font-mono">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 font-sans flex items-center gap-1.5">\n                            <span>🔷</span> Icosahedron (20 Faces)\n                        </h4>\n                        <div class="space-y-1 bg-slate-900/60 p-3 rounded-lg text-slate-200">\n                            <p>• Faces (F): <span class="text-emerald-400 font-bold">20</span> (Equilateral Triangles)</p>\n                            <p>• Vertices (V): <span class="text-cyan-400 font-bold">12</span> (5 triangles at each)</p>\n                            <p>• Edges (E): <span class="text-amber-400 font-bold">30</span></p>\n                            <p class="pt-1 border-t border-slate-700 font-sans text-[11px] text-slate-300">Euler Check: V - E + F = 12 - 30 + 20 = 2 ✓</p>\n                        </div>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n                        <h4 class="font-bold text-amber-400 mb-2 font-sans flex items-center gap-1.5">\n                            <span>⬟</span> Dodecahedron (12 Faces)\n                        </h4>\n                        <div class="space-y-1 bg-slate-900/60 p-3 rounded-lg text-slate-200">\n                            <p>• Faces (F): <span class="text-emerald-400 font-bold">12</span> (Regular Pentagons)</p>\n                            <p>• Vertices (V): <span class="text-cyan-400 font-bold">20</span> (3 pentagons at each)</p>\n                            <p>• Edges (E): <span class="text-amber-400 font-bold">30</span></p>\n                            <p class="pt-1 border-t border-slate-700 font-sans text-[11px] text-slate-300">Euler Check: V - E + F = 20 - 30 + 12 = 2 ✓</p>\n                        </div>\n                    </div>\n                </div>\n                <div class="p-3 bg-indigo-950/40 border border-indigo-500/30 rounded-lg text-xs text-indigo-200">\n                    <strong>Dual Polyhedra:</strong> The icosahedron and dodecahedron are geometric duals: swapping the centers of the icosahedron\'s 20 faces produces the 20 vertices of the dodecahedron!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_15', 'checkpoints': [{'question': 'What is the shape of each of the 20 faces of an icosahedron?', 'options': ['Equilateral triangle', 'Regular pentagon', 'Square', 'Hexagon'], 'correct': 0, 'explanation': 'An icosahedron has 20 congruent equilateral triangular faces.'}, {'question': "According to Euler's formula V - E + F = 2, if a polyhedron has 12 vertices and 20 faces, how many edges must it have?", 'options': ['30 edges', '32 edges', '28 edges', '24 edges'], 'correct': 0, 'explanation': 'V - E + F = 2 implies 12 - E + 20 = 2, so 32 - E = 2, which gives E = 30 edges.'}]}, {'id': 16, 'title': 'Skeletal Frames', 'tag': 'Straw and Clay Models • Structural Rigidity & 3D Engineering', 'lecture': 'We culminate our study by stepping into the boots of structural engineers! Using simple paper straws or bamboo sticks for edges, and small balls of modeling clay or play dough for vertices, we construct 3D skeletal frames of polyhedra. Build a square frame with four straws and four clay balls. Hold it up and push gently on two opposite corners: the square distorts easily into a slanted rhombus! It wobbles and collapses because a four-sided quadrilateral frame is mechanically unstable. Now insert a fifth diagonal straw across the square, dividing it into two triangles. Push again: the frame is now rock-solid and rigid! A triangle is the only polygon whose shape cannot be deformed without bending or breaking its edges. This is why construction cranes, railway bridges, electricity pylons, and geodesic domes are all built out of triangular trusses. By building cubes, tetrahedrons, and pyramids with straws and clay, we discover that mathematics is the invisible foundation supporting the bridges, buildings, and skyscrapers of our modern world.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Constructing skeletal models with straws (edges) and clay balls (vertices) reveals the principles of 3-D structural rigidity:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-teal-500/30">\n                        <h4 class="font-bold text-teal-400 mb-2 flex items-center gap-2">\n                            <span>🏗️</span> Triangulation & Rigidity\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>Square Frame (Wobbly):</strong> 4 straws + 4 clay balls deform into a rhombus under lateral shear force.</li>\n                            <li>• <strong>Diagonal Bracing:</strong> Adding 1 diagonal straw locks the angles completely, creating two rigid triangles.</li>\n                            <li>• <strong>Engineering Reality:</strong> High-voltage towers, roof trusses, and Ferris wheels rely on triangular bracing.</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 flex items-center gap-2">\n                            <span>📦</span> Polyhedral Skeletal Recipes\n                        </h4>\n                        <ul class="text-slate-300 space-y-1.5">\n                            <li>• <strong>Cube:</strong> 12 straws (equal length) + 8 clay balls.</li>\n                            <li>• <strong>Square Pyramid:</strong> 8 straws (4 base + 4 slant) + 5 clay balls.</li>\n                            <li>• <strong>Tetrahedron:</strong> 6 straws + 4 clay balls (inherently rigid!).</li>\n                            <li>• <strong>Octahedron:</strong> 12 straws + 6 clay balls.</li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-emerald-950/40 border border-emerald-500/30 rounded-lg text-xs text-emerald-200">\n                    <strong>Rigidity Principle:</strong> A triangle is rigid because its three side lengths uniquely fix all three interior angles. No angle can change without altering the side lengths!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_16', 'checkpoints': [{'question': 'How many clay balls (vertices) and straws (edges) are needed to build a skeletal cube?', 'options': ['8 clay balls and 12 straws', '6 clay balls and 12 straws', '8 clay balls and 6 straws', '12 clay balls and 8 straws'], 'correct': 0, 'explanation': 'A cube has 8 vertices (clay balls) and 12 edges (straws).'}, {'question': 'Why are bridge trusses and construction cranes built out of triangular frames rather than square frames?', 'options': ['Because triangles are structurally rigid and cannot deform without changing edge lengths', 'Because triangles look prettier', 'Because squares use fewer straws', 'Because triangles have four sides'], 'correct': 0, 'explanation': 'Triangles are inherently rigid; unlike squares, their angles cannot shift or collapse under external load.'}]}, {'id': 17, 'title': 'Challenge 1', 'tag': 'Mastery Challenge 1 • Weaving Patterns & Plane Tessellations', 'questions': [{'id': 1, 'question': "What happens if both Row 1 and Row 2 of a woven paper mat follow the exact same '1 over, 1 under' sequence without inverting?", 'options': ['The strips do not interlace and easily slide out without tension', 'The mat becomes twice as strong', 'It automatically creates a diamond pattern', 'The paper cuts itself'], 'correct': 0, 'solution_html': '<p>Inverting the sequence on alternating rows is essential for <strong>interlacing tension</strong>. Without alternating, the weft strips sit on the same side and slide out freely.</p>'}, {'id': 2, 'question': 'What must the sum of angles meeting at any vertex equal for tiles to tessellate without gaps or overlaps?', 'options': ['Exactly 360°', '180°', '540°', '90°'], 'correct': 0, 'solution_html': '<p>A full revolution around any point in a flat 2D plane is <strong>360°</strong>. For tiles to fit without gaps or overlap, the corner angles meeting at the vertex must sum to exactly 360°.</p>'}, {'id': 3, 'question': 'How many squares meet at each vertex in a standard square tessellation?', 'options': ['4 squares (4 × 90° = 360°)', '3 squares', '5 squares', '6 squares'], 'correct': 0, 'solution_html': '<p>Each square corner is 90°. Since 360° ÷ 90° = 4, exactly <strong>4 squares</strong> meet at each vertex.</p>'}, {'id': 4, 'question': 'Why can regular hexagons tessellate the plane by themselves?', 'options': ['Each corner is 120°, and 3 × 120° = 360°', 'Because they have 6 equal sides', 'Because 6 × 60° = 360°', 'Because they fit inside circles'], 'correct': 0, 'solution_html': '<p>A regular hexagon has interior angles of 120°. Exactly 3 hexagons meet at each vertex: 3 × 120° = <strong>360°</strong>.</p>'}, {'id': 5, 'question': 'Why do regular pentagons fail to tessellate a flat floor?', 'options': ['Each corner is 108°, and 108° does not evenly divide 360°', 'Because pentagons have an odd number of sides', 'Because 5 × 108° = 540°', 'Because pentagons are 3D solids'], 'correct': 0, 'solution_html': '<p>In a regular pentagon, each angle is 108°. 3 pentagons take 324° (leaving a 36° gap), while 4 pentagons take 432° (overlapping). Thus, 108° cannot divide 360° evenly.</p>'}, {'id': 6, 'question': 'In a semi-regular tessellation of octagons and squares, how many octagons and squares meet at each vertex?', 'options': ['2 octagons and 1 square (135° + 135° + 90° = 360°)', '1 octagon and 2 squares', '3 octagons and 1 square', '2 octagons and 2 squares'], 'correct': 0, 'solution_html': '<p>Each octagon angle is 135°, and each square angle is 90°. 135° + 135° + 90° = <strong>360°</strong>.</p>'}, {'id': 7, 'question': 'How many regular polygons are capable of monohedral (single-shape) regular tessellation?', 'options': ['Only 3 (Equilateral Triangle, Square, Regular Hexagon)', 'Only 2 (Square and Rectangle)', '5 regular polygons', 'All regular polygons'], 'correct': 0, 'explanation': 'Only equilateral triangles (60°), squares (90°), and regular hexagons (120°) have interior angles that divide 360° evenly.', 'solution_html': '<p>Only <strong>3 regular polygons</strong> can tile the plane by themselves: the equilateral triangle, the square, and the regular hexagon.</p>'}, {'id': 8, 'question': 'What is the angle measure of each interior corner of an equilateral triangle?', 'options': ['60°', '90°', '45°', '120°'], 'correct': 0, 'solution_html': '<p>An equilateral triangle has 3 equal angles summing to 180°: 180° ÷ 3 = <strong>60°</strong>.</p>'}, {'id': 9, 'question': "What type of weave pattern is created by '2 over, 1 under' with a one-unit shift each row?", 'options': ['Twill weave (diagonal staircases)', 'Plain weave', 'Square weave', 'Hexagonal weave'], 'correct': 0, 'solution_html': "<p>The '2 over, 1 under' pattern with row shifts produces a diagonal ridge texture known as a <strong>twill weave</strong> (like denim fabric).</p>"}, {'id': 10, 'question': 'How many equilateral triangles meet at a vertex to tile the plane?', 'options': ['6 triangles (6 × 60° = 360°)', '4 triangles', '8 triangles', '3 triangles'], 'correct': 0, 'solution_html': '<p>Each angle of an equilateral triangle is 60°. 360° ÷ 60° = <strong>6 triangles</strong>.</p>'}]}, {'id': 18, 'title': 'Challenge 2', 'tag': 'Mastery Challenge 2 • Triangle Classification & Kite Geometry', 'questions': [{'id': 11, 'question': 'A triangle has side lengths of 8 cm, 8 cm, and 5 cm. What type of triangle is it?', 'options': ['Isosceles triangle', 'Equilateral triangle', 'Scalene triangle', 'Right triangle'], 'correct': 0, 'solution_html': '<p>A triangle with at least two equal sides (8 cm and 8 cm) is an <strong>isosceles triangle</strong>.</p>'}, {'id': 12, 'question': 'If an isosceles triangle has a vertex angle of 40°, what is the measure of each of its two equal base angles?', 'options': ['70° each', '60° each', '80° each', '50° each'], 'correct': 0, 'solution_html': '<p>Sum of angles = 180°. Remaining for the 2 base angles = 180° - 40° = 140°. Each base angle = 140° ÷ 2 = <strong>70°</strong>.</p>'}, {'id': 13, 'question': 'A triangle has angle measures of 35°, 65°, and 80°. How is it classified by its sides?', 'options': ['Scalene triangle', 'Isosceles triangle', 'Equilateral triangle', 'Right-angled triangle'], 'correct': 0, 'solution_html': '<p>Since all three angles are different (35°, 65°, 80°), all three side lengths must be different: a <strong>scalene triangle</strong>.</p>'}, {'id': 14, 'question': 'Cutting a rhombus along both of its diagonals yields which four shapes?', 'options': ['Four identical right-angled triangles', 'Four equilateral triangles', 'Four squares', 'Two triangles and two rectangles'], 'correct': 0, 'solution_html': '<p>The diagonals of a rhombus are perpendicular bisectors, cutting it into <strong>4 congruent right-angled triangles</strong>.</p>'}, {'id': 15, 'question': 'Which of the following defines a kite quadrilateral?', 'options': ['Two pairs of adjacent equal sides', 'Two pairs of opposite equal sides', 'All four sides equal', 'Two pairs of parallel sides'], 'correct': 0, 'solution_html': '<p>A <strong>kite</strong> is defined by having two pairs of adjacent (neighboring) sides of equal length.</p>'}, {'id': 16, 'question': 'What is the angle of intersection between the two diagonals of a kite?', 'options': ['90° (Perpendicular)', '45°', '60°', '120°'], 'correct': 0, 'solution_html': '<p>In every kite, the two diagonals intersect at <strong>90° right angles</strong>.</p>'}, {'id': 17, 'question': 'How many lines of reflective symmetry does a non-rhombus kite possess?', 'options': ['Exactly 1 line (down its main diagonal)', '2 lines', '4 lines', '0 lines'], 'correct': 0, 'solution_html': '<p>A standard kite has <strong>exactly 1 line of symmetry</strong> passing through the vertices between the equal adjacent sides.</p>'}, {'id': 18, 'question': 'If a triangle has sides of 6 cm, 6 cm, and 6 cm, what are its three angle measures?', 'options': ['60°, 60°, 60°', '90°, 45°, 45°', '50°, 60°, 70°', '30°, 60°, 90°'], 'correct': 0, 'solution_html': '<p>An equilateral triangle with 3 equal sides always has 3 equal angles of <strong>60° each</strong>.</p>'}, {'id': 19, 'question': 'In a kite ABCD where AB = AD = 5 cm and CB = CD = 9 cm, which pair of angles are equal?', 'options': ['Angle B and Angle D', 'Angle A and Angle C', 'All four angles', 'None of the angles'], 'correct': 0, 'solution_html': '<p>In a kite, the angles between the unequal sides (∠ B and ∠ D) are <strong>equal</strong>.</p>'}, {'id': 20, 'question': 'What is the sum of the four interior angles of any quadrilateral (including a kite or rhombus)?', 'options': ['360°', '180°', '540°', '720°'], 'correct': 0, 'solution_html': '<p>Any quadrilateral can be split into 2 triangles: 2 × 180° = <strong>360°</strong>.</p>'}]}, {'id': 19, 'title': 'Challenge 3', 'tag': 'Mastery Challenge 3 • Quadrilateral Taxonomy, Tangrams & Deductions', 'questions': [{'id': 21, 'question': 'Which property is shared by BOTH a rectangle and a parallelogram?', 'options': ['Opposite sides are parallel and equal in length', 'All four angles must be 90°', 'Diagonals must be equal in length', 'All four sides must be equal'], 'correct': 0, 'solution_html': '<p>Both shapes have <strong>opposite sides that are parallel and equal in length</strong>. Right angles and equal diagonals belong specifically to rectangles.</p>'}, {'id': 22, 'question': 'A quadrilateral has 4 equal sides and diagonals that cross at 90°, but its angles are NOT 90°. What shape is it?', 'options': ['Rhombus', 'Square', 'Rectangle', 'Trapezoid'], 'correct': 0, 'solution_html': '<p>A shape with 4 equal sides and non-right angles is a <strong>rhombus</strong>.</p>'}, {'id': 23, 'question': 'Which shape is simultaneously a rectangle, a rhombus, and a parallelogram?', 'options': ['A square', 'A kite', 'A trapezium', 'An equilateral triangle'], 'correct': 0, 'solution_html': '<p>A <strong>square</strong> has 4 right angles (rectangle), 4 equal sides (rhombus), and parallel opposite sides (parallelogram).</p>'}, {'id': 24, 'question': 'How many pieces are in a standard tangram puzzle, and how many of them are triangles?', 'options': ['7 pieces total, with 5 triangles', '6 pieces total, with 4 triangles', '8 pieces total, with 6 triangles', '7 pieces total, with 3 triangles'], 'correct': 0, 'solution_html': '<p>A standard tangram has <strong>7 pieces</strong>: 2 large triangles, 1 medium triangle, 2 small triangles, 1 square, and 1 parallelogram (5 triangles in all).</p>'}, {'id': 25, 'question': 'What type of triangles are the 5 triangles in a tangram puzzle set?', 'options': ['45°-45°-90° isosceles right-angled triangles', 'Equilateral triangles (60°-60°-60°)', 'Scalene right-angled triangles', 'Obtuse triangles'], 'correct': 0, 'solution_html': '<p>All 5 tangram triangles are <strong>45°-45°-90° isosceles right triangles</strong>.</p>'}, {'id': 26, 'question': 'Which shape can be formed by joining the two small tangram triangles along their matching legs?', 'options': ['The medium triangle or the parallelogram', 'The large square', 'A circle', 'A pentagon'], 'correct': 0, 'solution_html': '<p>Joining the two small triangles along their legs can form either the <strong>medium triangle</strong> or the <strong>parallelogram</strong> (or the small square if joined along hypotenuses).</p>'}, {'id': 27, 'question': "Riddle: 'I have four sides. My opposite sides are equal, all four of my angles are 90°, and my diagonals are equal in length.' Which shape am I?", 'options': ['Rectangle', 'Rhombus', 'Kite', 'Parallelogram'], 'correct': 0, 'solution_html': '<p>Opposite sides equal, four 90° angles, and equal diagonals uniquely identify a <strong>rectangle</strong>.</p>'}, {'id': 28, 'question': "Riddle: 'I have four sides. Two adjacent pairs of sides are equal, my diagonals meet at 90°, and I have only 1 line of symmetry.' Which shape am I?", 'options': ['Kite', 'Square', 'Rectangle', 'Rhombus'], 'correct': 0, 'solution_html': '<p>Two adjacent equal pairs, perpendicular diagonals, and 1 symmetry line uniquely identify a <strong>kite</strong>.</p>'}, {'id': 29, 'question': 'When folding a square paper diagonally corner-to-corner to start an origami kite, what does the crease represent?', 'options': ['The central line of symmetry of the kite', 'The perimeter of the square', 'A curved arc', 'The shortest side'], 'correct': 0, 'solution_html': '<p>The diagonal crease forms the <strong>line of reflective symmetry</strong> for the folded kite wings.</p>'}, {'id': 30, 'question': 'If you rearrange all 7 tangram pieces into the shape of a running person, how does the total area compare to the original square?', 'options': ['The area is exactly the same', 'The area increases', 'The area decreases by half', 'It depends on how pieces are arranged'], 'correct': 0, 'solution_html': '<p>By the <strong>Conservation of Area</strong> principle, rearranging pieces without overlap preserves the exact total area.</p>'}]}, {'id': 20, 'title': 'Challenge 4', 'tag': 'Mastery Challenge 4 • Circle Constructions, 3D Solids & Platonic Geometry', 'questions': [{'id': 31, 'question': 'If two diameters of a circle are drawn perpendicular (at 90°) to each other, connecting their 4 endpoints creates which shape?', 'options': ['A square', 'A general rectangle', 'A trapezoid', 'A rhombus with non-right angles'], 'correct': 0, 'solution_html': '<p>Because the diameters are equal, bisect each other, and cross at 90°, connecting their endpoints produces a <strong>square</strong>.</p>'}, {'id': 32, 'question': 'On a circle with 24 evenly spaced points, what is the angle between point 1 and point 7?', 'options': ['90° (6 steps × 15°)', '105°', '60°', '75°'], 'correct': 0, 'solution_html': '<p>Each step is 360° ÷ 24 = 15°. From point 1 to 7 is 6 steps: 6 × 15° = <strong>90°</strong> (a right angle!).</p>'}, {'id': 33, 'question': 'How many valid unfolded hexomino nets can fold into a closed 3-D cube?', 'options': ['11 nets', '6 nets', '12 nets', '8 nets'], 'correct': 0, 'solution_html': '<p>There are mathematically exactly <strong>11 valid nets</strong> that can fold into a closed cube.</p>'}, {'id': 34, 'question': 'In a 3×3×3 painted cube cut into 27 small 1cm cubes, how many cubes have exactly TWO painted faces?', 'options': ['12 cubes (along the edges)', '8 cubes', '6 cubes', '1 cube'], 'correct': 0, 'solution_html': '<p>A cube has 12 edges. Each edge has 1 middle cube with 2 painted faces: 12 × 1 = <strong>12 cubes</strong>.</p>'}, {'id': 35, 'question': 'In the same 3×3×3 painted cube, how many small cubes have exactly ONE painted face?', 'options': ['6 cubes (one at the center of each face)', '12 cubes', '8 cubes', '0 cubes'], 'correct': 0, 'solution_html': '<p>A cube has 6 faces. Each face center has 1 cube with 1 painted face: 6 × 1 = <strong>6 cubes</strong>.</p>'}, {'id': 36, 'question': 'What regular polygon forms all 20 faces of an icosahedron?', 'options': ['Equilateral triangle', 'Regular pentagon', 'Square', 'Hexagon'], 'correct': 0, 'solution_html': '<p>An icosahedron has 20 congruent <strong>equilateral triangular faces</strong>.</p>'}, {'id': 37, 'question': 'How many regular pentagonal faces does a dodecahedron have?', 'options': ['12 faces', '20 faces', '10 faces', '30 faces'], 'correct': 0, 'solution_html': "<p>'Dodeca' means 12. A dodecahedron has <strong>12 regular pentagonal faces</strong>.</p>"}, {'id': 38, 'question': "According to Euler's formula V - E + F = 2, if a dodecahedron has 12 faces and 30 edges, how many vertices must it have?", 'options': ['20 vertices', '12 vertices', '24 vertices', '18 vertices'], 'correct': 0, 'solution_html': '<p>V - 30 + 12 = 2 ➔ V - 18 = 2 ➔ V = <strong>20 vertices</strong>.</p>'}, {'id': 39, 'question': 'Why does a 4-sided square frame made of straws and clay wobble and collapse, while a triangular frame remains rigid?', 'options': ["A triangle's side lengths uniquely fix its three angles, making it inherently rigid", 'Squares have weaker clay balls', 'Straws are only strong in odd numbers', 'Squares cannot hold vertical weight'], 'correct': 0, 'solution_html': '<p>A triangle is <strong>structurally rigid</strong> because its 3 edge lengths uniquely fix all 3 angles; a square frame can deform into a rhombus without changing side lengths.</p>'}, {'id': 40, 'question': 'How many straws (edges) and clay balls (vertices) are needed to build a skeletal square pyramid?', 'options': ['8 straws and 5 clay balls', '6 straws and 4 clay balls', '12 straws and 8 clay balls', '8 straws and 6 clay balls'], 'correct': 0, 'solution_html': '<p>A square pyramid has 4 base edges + 4 slant edges = <strong>8 straws</strong>, and 4 base vertices + 1 apex vertex = <strong>5 clay balls</strong>.</p>'}]}]
